export const releaseStatus = pgEnum("release_status", ["candidate", "published", "retired"]);
export const missingReason = pgEnum("missing_reason", ["not_applicable", "not_collected", "not_reported", "not_yet_reported", "suppressed", "unmatched", "source_unavailable", "not_defensibly_modeled", "license_unavailable"]);
