export const rawStoreKind = pgEnum("raw_store_kind", ["local", "s3"]);
export const ingestFailureCode = pgEnum("ingest_failure_code", ["ingest_error", "lease_expired"]);
export const geometry = customType<{ data: string; driverData: string }>({ dataType: () => "geometry(MultiPolygon,4326)" });
const id = (name: string) => text(name).notNull();
const release = () => id("release_id").references(() => dataReleases.id);
const factNumber = (name: string) => numeric(name);

